package android.view;public class ViewTreeObserver{public interface OnPreDrawListener{boolean onPreDraw();}public java.util.ArrayList<OnPreDrawListener> pre=new java.util.ArrayList<>();public void addOnPreDrawListener(OnPreDrawListener l){pre.add(l);}public void removeOnPreDrawListener(OnPreDrawListener l){pre.remove(l);}public boolean draw(){boolean yes=true;for(OnPreDrawListener l:new java.util.ArrayList<>(pre))yes&=l.onPreDraw();return yes;}
public interface OnGlobalLayoutListener{void onGlobalLayout();}public java.util.ArrayList<OnGlobalLayoutListener> listeners=new java.util.ArrayList<>();public boolean isAlive(){return true;}public void addOnGlobalLayoutListener(OnGlobalLayoutListener l){listeners.add(l);}public void removeOnGlobalLayoutListener(OnGlobalLayoutListener l){listeners.remove(l);}public void global(){for(OnGlobalLayoutListener l:new java.util.ArrayList<>(listeners))l.onGlobalLayout();}}